(7470284, 1186692, 12611, '<td valign="top">I am not sure about the lighting, but the colors of blue and clay are spot on.</td>', 'I am not sure about the lighting, but the colors of blue and clay are spot on.', '2016-08-30 12:59:33.000000', NULL, 1),
(7470285, 1186707, 12611, '<td valign="top">beautiful scene.</td>', 'beautiful scene.', '2016-08-30 12:59:54.000000', NULL, 1),
