(7470290, 1186450, 12611, '<td valign="top">Your color spectrum is out of control. beautiful work, I am especially drawn to the purple rim.</td>', 'Your color spectrum is out of control. beautiful work, I am especially drawn to the purple rim.', '2016-08-30 13:02:17.000000', NULL, 1),
(7470291, 1186461, 12611, '<td valign="top">The sense of scale confirmed by the people makes the shot imo.</td>', 'The sense of scale confirmed by the people makes the shot imo.', '2016-08-30 13:02:44.000000', NULL, 1),
(7470294, 1186418, 66384, '<td valign="top">I would prefer to see the shadows opened up a bit to give more detail to the rocks. As it is, it is a nice sunset, but I don''t get a feel for the place.</td>', 'I would prefer to see the shadows opened up a bit to give more detail to the rocks. As it is, it is a nice sunset, but I don''t get a feel for the place.', '2016-08-30 14:28:38.000000', NULL, 1),
(7470295, 1186442, 66384, '<td valign="top">Beautiful place and nice color. The foreground seems over sharpened, and that is distracting.</td>', 'Beautiful place and nice color. The foreground seems over sharpened, and that is distracting.', '2016-08-30 14:30:35.000000', NULL, 1),
(7470296, 1186719, 66384, '<td valign="top">Beautiful mood and nice tone.</td>', 'Beautiful mood and nice tone.', '2016-08-30 14:31:18.000000', NULL, 1),
