(7470471, 1186478, 181847, '<td valign="top">Would have been nice shot if you had waited for the motorcycles to pass by.</td>', 'Would have been nice shot if you had waited for the motorcycles to pass by.', '2016-08-31 11:41:58.000000', NULL, 1),
