(7470473, 1186623, 181847, '<td valign="top">Over-saturated colors.</td>', 'Over-saturated colors.', '2016-08-31 11:45:31.000000', NULL, 1),
(7470476, 1186718, 181847, '<td valign="top">When I compare this shot to the  10000''s of shots I have seen from this location it is anther "me too" shot. Nice clear day with good view of Tetons. This location is worthy of effort to get there at sunrise or sunset.</td>', 'When I compare this shot to the  10000''s of shots I have seen from this location it is anther "me too" shot. Nice clear day with good view of Tetons. This location is worthy of effort to get there at sunrise or sunset.', '2016-08-31 12:28:26.000000', NULL, 1),
(7470477, 1186527, 181847, '<td valign="top">Nice sunset. Would have been nicer if you had walked a few feet to get the road out of the shot.</td>', 'Nice sunset. Would have been nicer if you had walked a few feet to get the road out of the shot.', '2016-08-31 12:29:43.000000', NULL, 1),
(7470479, 1186349, 181847, '<td valign="top">Feel like the color of the flowers is over saturated. Detracts from an otherwise great shot.</td>', 'Feel like the color of the flowers is over saturated. Detracts from an otherwise great shot.', '2016-08-31 12:37:53.000000', NULL, 1),
(7470482, 1186570, 181847, '<td valign="top">It may be a personal pet peeve but I feel this is like many other photos I see where the photographer has pushed the saturation slider too far to the right. I have never seen a sunset produce that level of oranges &amp; reds in real life. A great shot spoiled by over emphasizing colors.</td>', 'It may be a personal pet peeve but I feel this is like many other photos I see where the photographer has pushed the saturation slider too far to the right. I have never seen a sunset produce that level of oranges & reds in real life. A great shot spoiled by over emphasizing colors.', '2016-08-31 12:42:01.000000', NULL, 1),
(7470483, 1186710, 181847, '<td valign="top">I can almost hear the sounds and smell the smells of the early morning. I would have boosted the shadows just a bit if the noise level allowed.</td>', 'I can almost hear the sounds and smell the smells of the early morning. I would have boosted the shadows just a bit if the noise level allowed.', '2016-08-31 12:44:24.000000', NULL, 1),
