(7471592, 1186632, 114285, '<td valign="top">Excellent editing, rich contrast, gorgeous scene especially the clouds. I might of cropped a touch off the top because those clouds above the peak are extra special. I also wish you had of shared the location.</td>', 'Excellent editing, rich contrast, gorgeous scene especially the clouds. I might of cropped a touch off the top because those clouds above the peak are extra special. I also wish you had of shared the location.', '2016-09-03 22:07:53.000000', NULL, 1),
(7471641, 1186625, 7889, '<td valign="top">Brilliant !</td>', 'Brilliant !', '2016-09-04 08:15:49.000000', NULL, 1),
(7471646, 1186552, 98565, '<td valign="top">These colours are yelling at me</td>', 'These colours are yelling at me', '2016-09-04 10:54:59.000000', NULL, 1),
(7471764, 1186590, 30982, '<td valign="top">I Love the harsh contrast in this.  Something very striking about the photograph.  First one that has inspired me to comment so far, too.</td>', 'I Love the harsh contrast in this.  Something very striking about the photograph.  First one that has inspired me to comment so far, too.', '2016-09-04 17:43:36.000000', NULL, 1),
(7471772, 1186454, 30982, '<td valign="top">I hope folks linger long enough to see the true scale...</td>', 'I hope folks linger long enough to see the true scale...', '2016-09-04 17:56:45.000000', NULL, 1),
(7471774, 1186338, 30982, '<td valign="top">Lovely tones, beautiful composition.</td>', 'Lovely tones, beautiful composition.', '2016-09-04 17:57:03.000000', NULL, 1),
(7471776, 1186641, 92512, '<td valign="top">I somehow missed seeing this when I was there. Thanks for sharing.</td>', 'I somehow missed seeing this when I was there. Thanks for sharing.', '2016-09-04 18:06:09.000000', NULL, 1),
(7471777, 1186426, 92512, '<td valign="top">Excellent view. I like the way you captured the different angle of the sun''s rays.</td>', 'Excellent view. I like the way you captured the different angle of the sun''s rays.', '2016-09-04 18:08:34.000000', NULL, 1),
(7471779, 1186519, 92512, '<td valign="top">Great use of depth of field to focus on the subject.</td>', 'Great use of depth of field to focus on the subject.', '2016-09-04 18:09:44.000000', NULL, 1),
(7471780, 1186586, 92512, '<td valign="top">Beautiful, this is something I would like to see in person one day.</td>', 'Beautiful, this is something I would like to see in person one day.', '2016-09-04 18:11:45.000000', NULL, 1),
(7471782, 1186644, 92512, '<td valign="top">Good job with the Black and white to capture all the details.</td>', 'Good job with the Black and white to capture all the details.', '2016-09-04 18:13:32.000000', NULL, 1),
(7471783, 1186339, 92512, '<td valign="top">Sharp image! Very nicely done.</td>', 'Sharp image! Very nicely done.', '2016-09-04 18:15:17.000000', NULL, 1),
(7471786, 1186457, 92512, '<td valign="top">fantastic view I enjoy all the different colors.</td>', 'fantastic view I enjoy all the different colors.', '2016-09-04 18:17:33.000000', NULL, 1),
(7471791, 1186362, 92512, '<td valign="top">Amazing so much to take in at once. I could spend hours looking at this.</td>', 'Amazing so much to take in at once. I could spend hours looking at this.', '2016-09-04 18:20:25.000000', NULL, 1),
(7471795, 1186462, 92512, '<td valign="top">Great capture, excellent work.</td>', 'Great capture, excellent work.', '2016-09-04 18:21:54.000000', NULL, 1),
(7471797, 1186662, 92512, '<td valign="top">Very interesting, and colorful. nicely done.</td>', 'Very interesting, and colorful. nicely done.', '2016-09-04 18:27:46.000000', NULL, 1),
(7471849, 1186498, 30982, '<td valign="top">Very interesting structure and really nicely presented in B&amp;W.</td>', 'Very interesting structure and really nicely presented in B&W.', '2016-09-04 19:19:38.000000', NULL, 1),
(7471851, 1186384, 30982, '<td valign="top">Beautifully rendered; feels a bit lonely but ever so peaceful.</td>', 'Beautifully rendered; feels a bit lonely but ever so peaceful.', '2016-09-04 19:21:01.000000', NULL, 1),
(7471852, 1186389, 30982, '<td valign="top">What a stunning sky!</td>', 'What a stunning sky!', '2016-09-04 19:21:23.000000', NULL, 1),
(7471855, 1186638, 30982, '<td valign="top">Postcard perfect with lovely light.</td>', 'Postcard perfect with lovely light.', '2016-09-04 19:22:13.000000', NULL, 1),
(7471857, 1186462, 30982, '<td valign="top">That sky really adds a wonderful element here - but I love the rocks.  Very nice presentation!</td>', 'That sky really adds a wonderful element here - but I love the rocks.  Very nice presentation!', '2016-09-04 19:22:55.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7471859, 1186718, 30982, '<td valign="top">Wonderfully composed.  And rich blues really set this off.</td>', 'Wonderfully composed.  And rich blues really set this off.', '2016-09-04 19:23:22.000000', NULL, 1),
(7471860, 1186642, 30982, '<td valign="top">Gotta love the light in this!</td>', 'Gotta love the light in this!', '2016-09-04 19:23:34.000000', NULL, 1),
(7472000, 1186498, 114285, '<td valign="top">Makes me wonder how they''re all stuck there like that,  love this one</td>', 'Makes me wonder how they''re all stuck there like that,  love this one', '2016-09-05 05:12:25.000000', NULL, 1),
(7472001, 1186638, 114285, '<td valign="top">Has Dennis written all over it, maybe :)<br/> <br/>Gorgeous in every way, has a bit of everything in it, mountains, waterfall, still waters and a dynamic sunset. Sharp, beautifully presented in all ways.  Overall top stuff, and my top pick!<br/> <br/>BTW I looked up Elysian Fields, and it comes up on google as a mythological place, so I''m looking forward to seeing where this is.</td>', 'Has Dennis written all over it, maybe :) Gorgeous in every way, has a bit of everything in it, mountains, waterfall, still waters and a dynamic sunset. Sharp, beautifully presented in all ways.  Overall top stuff, and my top pick! BTW I looked up Elysian Fields, and it comes up on google as a mythological place, so I''m looking forward to seeing where this is.', '2016-09-05 05:16:57.000000', NULL, 1),
(7472007, 1186359, 119419, '<td valign="top">Nice background bokeh</td>', 'Nice background bokeh', '2016-09-05 05:53:27.000000', NULL, 1),
(7472008, 1186464, 119419, '<td valign="top">That''s a nice ridge, the path distracts but is a pleasant feature on its'' own.</td>', 'That''s a nice ridge, the path distracts but is a pleasant feature on its'' own.', '2016-09-05 05:54:37.000000', NULL, 1),
(7472009, 1186448, 119419, '<td valign="top">I like the leading line to the brighter opening.</td>', 'I like the leading line to the brighter opening.', '2016-09-05 05:55:29.000000', NULL, 1),
(7472010, 1186736, 119419, '<td valign="top">Quite a panorama.</td>', 'Quite a panorama.', '2016-09-05 05:56:33.000000', NULL, 1),
(7472011, 1186664, 119419, '<td valign="top">Great symmetry and a good job on the toning.</td>', 'Great symmetry and a good job on the toning.', '2016-09-05 05:57:49.000000', NULL, 1),
(7472012, 1186659, 119419, '<td valign="top">Very poetic.</td>', 'Very poetic.', '2016-09-05 05:58:39.000000', NULL, 1),
(7472013, 1186716, 119419, '<td valign="top">Delightful abstract.</td>', 'Delightful abstract.', '2016-09-05 05:59:10.000000', NULL, 1),
